// Carry forward the original trigger data alongside the AI config, since the
// next node (Google Calendar) needs tenant date range + calendar id together.
const trigger = $('When Executed by Another Workflow').first().json;
const config = $json;
return [{
  json: {
    tenant_id: trigger.tenant_id,
    date_range_start: trigger.date_range_start,
    date_range_end: trigger.date_range_end,
    business_hours: config.business_hours,
    timezone: config.timezone || 'UTC',
    google_calendar_id: config.google_calendar_id || 'primary'
  }
}];

// Compute open appointment slots: business_hours minus existing calendar events.
const config = $('Merge Config').first().json;
const freeBusyResult = $input.first().json;
const calendarId = config.google_calendar_id || 'primary';
const busy = (freeBusyResult.calendars?.[calendarId]?.busy) || [];
const businessHours = config.business_hours || {};
const timezone = config.timezone || 'UTC';
const SLOT_MINUTES = 60;
// Safety cap on the total number of slots returned across the whole date range,
// so a wide range does not produce an unbounded payload. Set high enough to
// cover a full multi-day business week of hourly slots (previously this was 5,
// which truncated a single day and hid real availability like 2pm-5pm).
const MAX_SLOTS = 200;
const dayNames = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];

const busyRanges = busy.map(b => ({
  start: DateTime.fromISO(b.start),
  end: DateTime.fromISO(b.end)
}));

function overlaps(slotStart, slotEnd) {
  return busyRanges.some(b => slotStart < b.end && slotEnd > b.start);
}

const startDate = DateTime.fromISO(config.date_range_start, { zone: timezone }).startOf('day');
const endDate = DateTime.fromISO(config.date_range_end, { zone: timezone }).startOf('day');
const now = DateTime.now().setZone(timezone);
const slots = [];

for (let d = startDate; d <= endDate && slots.length < MAX_SLOTS; d = d.plus({ days: 1 })) {
  const dayName = dayNames[d.weekday % 7];
  const hours = businessHours[dayName];
  if (!hours) continue;

  const [openH, openM] = hours.open.split(':').map(Number);
  const [closeH, closeM] = hours.close.split(':').map(Number);

  let slotStart = d.set({ hour: openH, minute: openM, second: 0, millisecond: 0 });
  const dayClose = d.set({ hour: closeH, minute: closeM, second: 0, millisecond: 0 });

  while (slotStart < dayClose && slots.length < MAX_SLOTS) {
    const slotEnd = slotStart.plus({ minutes: SLOT_MINUTES });
    if (slotEnd <= dayClose && slotStart > now && !overlaps(slotStart, slotEnd)) {
      slots.push({
        starts_at: slotStart.toUTC().toISO(),
        ends_at: slotEnd.toUTC().toISO()
      });
    }
    slotStart = slotStart.plus({ minutes: SLOT_MINUTES });
  }
}

return [{ json: { available_slots: slots, timezone: config.timezone } }];
